-- Footer: remove the Wire, Features and Reviews links (and the account link,
-- now staff-only), dropping any column left empty. About page: fuller copy
-- written for search (19 Nov 2026). 'main' only; safe to re-run.
UPDATE "publications" SET "settings" = jsonb_set("settings", '{footer}', (
  SELECT coalesce(jsonb_agg(col ORDER BY ci), '[]'::jsonb) FROM (
    SELECT ci, jsonb_set(c, '{links}', coalesce((
      SELECT jsonb_agg(l ORDER BY li) FROM jsonb_array_elements(c->'links') WITH ORDINALITY AS x(l, li)
      WHERE l->>'href' NOT IN ('/news', '/features', '/reviews', '/account')
    ), '[]'::jsonb)) AS col
    FROM jsonb_array_elements("settings"->'footer') WITH ORDINALITY AS y(c, ci)
  ) z WHERE jsonb_array_length(col->'links') > 0
)), "updated_at" = now()
WHERE "slug" = 'main' AND jsonb_typeof("settings"->'footer') = 'array';
